script:
window.frappe = {}
document.addEventListener("DOMContentLoaded", function () {
    const currentPath = window.location.pathname.replace(/\/$/, "");

    document.querySelectorAll(".hover-navbar-text").forEach(link => {
        const linkPath = new URL(link.href).pathname.replace(/\/$/, "");

        if (linkPath === currentPath) {
            link.classList.add("active");
        }
    });
});
document.addEventListener("DOMContentLoaded", function () {
    let lastScrollY = 0;

    function animateText(isInitialLoad = false) {
        const elements = document.querySelectorAll(".fade-3d");
        const counters = document.querySelectorAll(".counter");

        const vh = window.innerHeight;
        const currentScrollY = window.scrollY;
        const scrollingDown = currentScrollY > lastScrollY || isInitialLoad;

        // Fade animations (allow on load)
        elements.forEach(el => {
            const rect = el.getBoundingClientRect();

            if (
                rect.top < vh * 1.1 &&
                rect.bottom > 0 &&
                !el.classList.contains("in")
            ) {
                el.classList.add("in");
            }
        });

        // Counter animations (ONLY when scrolling down)
        counters.forEach(el => {
            const rect = el.getBoundingClientRect();

            if (
                rect.top < vh * 1.1 &&
                rect.bottom > 0 &&
                !el.dataset.animated
            ) {
                animateCounter(el);
                el.dataset.animated = "true";
            }
        });

        lastScrollY = currentScrollY;
    }

    function animateCounter(el, duration = 3000) {
        const target = parseInt(el.dataset.target, 10);
        const startTime = performance.now();

        function update(now) {
            const elapsed = now - startTime;
            const progress = Math.min(elapsed / duration, 1);
            el.textContent = Math.floor(progress * target) + "%";

            if (progress < 1) {
                requestAnimationFrame(update);
            }
        }

        requestAnimationFrame(update);
    }

    // Correct event bindings
    window.addEventListener("load", () => animateText(true));
    window.addEventListener("scroll", animateText);

    const mobileNav = document.getElementById("mobile-nav");
    const openBtn = document.getElementById("mobile-nav-button");
    const closeBtn = document.getElementById("mobile-nav-close");

    openBtn.addEventListener("click", () => {
        mobileNav.classList.add("is-open");
    });

    closeBtn.addEventListener("click", () => {
        mobileNav.classList.remove("is-open");
    });

    const cart = document.getElementById("cart-drawer");
    const cartOpenBtn = document.getElementById("cart-open-button");
    const cartCloseBtn = document.getElementById("cart-close-button");

    cartOpenBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        cart.classList.add("is-open");
        get_cart_items();
    });

    cartCloseBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        cart.classList.remove("is-open");
    });

    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape") {
            cart.classList.remove("is-open");
        }
    });

    document.addEventListener("click", (e) => {
        if (
            cart.classList.contains("is-open") &&
            !cart.contains(e.target)
        ) {
            cart.classList.remove("is-open");
        }
    });

    // const search = document.getElementById("search-container");
    // const searchOpenBtn = document.getElementById("search-open-button");
    // const searchCloseBtn = document.getElementById("search-close-button");

    // searchOpenBtn.addEventListener("click", () => {
    //   search.classList.add("is-open");
    // });

    // searchCloseBtn.addEventListener("click", () => {
    //   search.classList.remove("is-open");
    // });


    const description = document.getElementById("description_drawer");
    const descriptionOpenBtn = document.getElementById("description-open-button");
    const descriptionCloseBtn = document.getElementById("description-close-button");

    if (description && descriptionOpenBtn && descriptionCloseBtn) {
        descriptionOpenBtn.addEventListener("click", () => {
            description.classList.add("is-open");
        });

        descriptionCloseBtn.addEventListener("click", () => {
            description.classList.remove("is-open");
        });
    }

    const filter = document.getElementById("filter-drawer");
    const filterOpenBtn = document.getElementById("filter-open-button");
    const filterCloseBtn = document.getElementById("filter-close-button");

    if (filter && filterOpenBtn && filterCloseBtn) {

        filterOpenBtn.addEventListener("click", () => {
            filter.classList.add("is-open");

            const filterContainer = document.getElementById("filter-container");
            const mobileContainer = document.getElementById("filter-mobile-container");

            while (filterContainer.firstChild) {
                mobileContainer.appendChild(filterContainer.firstChild);
            }
        });

        filterCloseBtn.addEventListener("click", () => {
            filter.classList.remove("is-open");

            const filterContainer = document.getElementById("filter-container");
            const mobileContainer = document.getElementById("filter-mobile-container");

            while (mobileContainer.firstChild) {
                filterContainer.appendChild(mobileContainer.firstChild);
            }
        });
    }



    const CSRF_TOKEN = frappe.csrf_token
    const HEADERS = {
        "Content-Type": "application/json",
        "x-frappe-csrf-token": CSRF_TOKEN,
        "x-requested-with": "XMLHttpRequest",
        Accept: "application/json, text/javascript, */*; q=0.01"
    }



    function updateAddressPreview(addressType, addressName) {
        fetch(`/api/resource/Address/${addressName}`)
            .then(res => res.json())
            .then(({
                data
            }) => {
                if (!data) return;

                const preview = document.getElementById(
                    addressType === "billing" ? "address_preview" : "shipping_address_preview"
                );

                if (preview) {
                    preview.querySelector(".address_line1").innerHTML = data.address_line1 || '';
                    preview.querySelector(".city").innerHTML = data.city || '';
                    preview.querySelector(".country").innerHTML = data.country || '';
                    preview.querySelector(".pincode").innerHTML = data.pincode || '';
                    preview.querySelector(".phone").innerHTML = data.phone || '';
                }
            })
            .catch(err => {
                console.error("Error fetching address:", err);
            });
    }

    // Billing Radio Listener
    document.querySelectorAll('.billing-radio').forEach(input => {
        input.addEventListener('change', () => {
            if (input.checked) {
                updateAddressPreview("billing", input.value);

                // Update Quotation Address on backend and refresh UI
                updateCartAddress("billing", input.value);

                let deliverSameInput = document.querySelector('[name="deliver_same"]');
                if (deliverSameInput && deliverSameInput.checked) {
                    updateAddressPreview("shipping", input.value);
                    updateCartAddress("shipping", input.value);
                }
            }
        });
    });

    // Shipping Radio Listener
    document.querySelectorAll('.shipping-radio').forEach(input => {
        input.addEventListener('change', () => {
            if (input.checked) {
                updateAddressPreview("shipping", input.value);

                // Update Quotation Shipping Address and Refresh totals
                updateCartAddress("shipping", input.value);
            }
        });
    });

    /**
     * Updates the address on the Quotation backend
     * @param {string} type - "billing" or "shipping"
     * @param {string} addressName - The name (ID) of the Address doc
     */
    function updateCartAddress(type, addressName) {
        fetch('/api/method/invento_webshop.webshop_functions.cart.update_cart_address', {
            method: 'POST',
            headers: HEADERS,
            body: JSON.stringify({
                address_type: type,
                address_name: addressName
            })
        })
            .then(res => res.json())
            .then(data => {
                get_cart_items();
            })
            .catch(err => console.error("Error updating cart address:", err));
    }


    const placeOrderBtn = document.getElementById("submit-order");
    if (placeOrderBtn) {
        placeOrderBtn.addEventListener("submit", async function (event) {
            event.preventDefault();
            event.stopPropagation();

            const formData = new FormData(this);
            const jsonData = Object.fromEntries(formData.entries());

            const payload = {
                doc: jsonData,
                cart_items: frappe.get_cookie("cart_items")
            };

            let result;
            try {
                const response = await fetch("/api/method/invento_webshop.webshop_functions.cart.place_order", {
                    method: "POST",
                    headers: HEADERS,
                    body: JSON.stringify(payload)
                });
                result = await response.json();
            } catch (err) {
                Toastify({
                    text: "Network error. Please try again.",
                    close: true, gravity: "top", position: "center", stopOnFocus: true,
                    style: { background: "linear-gradient(to right, #ff5f6d, #ffc371)" }
                }).showToast();
                return;
            }

            if (result.message) {
                // Card payment: Quotation was submitted; SO will be created after gateway confirms.
                // Redirect to initiate_quotation_payment — Frappe will then redirect to Lloyds Connect.
                if (result.message.pending_card_payment && result.message.quotation) {
                    window.location.href =
                        "/api/method/invento_webshop.api.sales_order_payment.initiate_quotation_payment?quotation=" +
                        result.message.quotation;
                    return;
                }

                // Non-card: order is confirmed — show success UI.
                Toastify({
                    text: "Order placed successfully!",
                    close: true,
                    gravity: "top",
                    position: "center",
                    stopOnFocus: true,
                    style: { background: "linear-gradient(to right, #00b09b, #96c93d)" }
                }).showToast();

                get_cart_count();

                const placeOrderDiv = document.getElementById("submit-order");
                const successOrderDiv = document.getElementById("order_sucess");
                const orderIdElement = document.getElementById("order_id");
                const itemContainer = document.getElementById("item_container");

                if (placeOrderDiv) placeOrderDiv.style.display = "none";
                if (successOrderDiv) successOrderDiv.style.display = "flex";

                if (orderIdElement && result.message.name) {
                    orderIdElement.innerHTML = result.message.name;
                }

                if (itemContainer && result.message.items && result.message.items.length > 0) {
                    const originalHTML = itemContainer.querySelector("div").cloneNode(true);
                    itemContainer.innerHTML = "";

                    result.message.items.forEach(item => {
                        const itemNode = originalHTML.cloneNode(true);

                        const imageElement = itemNode.querySelector(".item_image");
                        if (imageElement) imageElement.src = item.image;

                        const nameElement = itemNode.querySelector(".item_name");
                        if (nameElement) nameElement.innerText = item.item_name;

                        const priceElement = itemNode.querySelector(".item_price");
                        if (priceElement) priceElement.innerText = item.amount;

                        itemContainer.appendChild(itemNode);
                    });

                    window.scrollTo({ top: 0, behavior: "smooth" });
                }

            } else if (result._server_messages) {
                try {
                    const messages = JSON.parse(result._server_messages);
                    let fullMessage = "";
                    let creditLimitDetected = false;

                    messages.forEach(msgStr => {
                        const msgObj = JSON.parse(msgStr);
                        if (msgObj.message && msgObj.message.toLowerCase().includes("credit limit")) {
                            creditLimitDetected = true;
                        }
                        fullMessage += msgObj.message + "<br><br>";
                    });

                    if (creditLimitDetected) {
                        showWarningModal("Your credit limit has been crossed or expired. Please contact us.");
                    } else {
                        showWarningModal(fullMessage);
                    }
                } catch (e) {
                    console.error("Error parsing server messages", e);
                    Toastify({
                        text: "Payment gateway configuration error. Please contact support.",
                        close: true, gravity: "top", position: "center", stopOnFocus: true,
                        style: { background: "linear-gradient(to right, #ff5f6d, #ffc371)" }
                    }).showToast();
                }
            }
        });
    }



    document.querySelectorAll(".add-to-cart").forEach(button => {
        button.addEventListener("click", function () {
            let itemCode = this.getAttribute("data-item_code");
            if (!itemCode) return;

            addToCart(itemCode, 1)
        });
    });


    document.querySelectorAll(".qty-minus").forEach(button => {
        button.addEventListener("click", function () {
            const wrapper = this.closest(".cart-qty-update");
            if (!wrapper) return;

            const input = wrapper.querySelector(".item-qty");
            let current = parseInt(input.value) || 1;

            if (current > 1) {
                input.value = current - 1;
            }
        });
    });

    document.querySelectorAll(".qty-plus").forEach(button => {
        button.addEventListener("click", function () {
            const wrapper = this.closest(".cart-qty-update");
            if (!wrapper) return;

            const input = wrapper.querySelector(".item-qty");
            let current = parseInt(input.value) || 1;

            input.value = current + 1;
        });
    });

    document.querySelectorAll(".add-to-cart-details").forEach(button => {
        button.addEventListener("click", function () {
            const itemCode = this.getAttribute("data-item_code");
            if (!itemCode) return;

            // Get closest cart wrapper
            const wrapper = this.closest(".cart-qty-update");
            if (!wrapper) return;

            // Get quantity input inside this wrapper
            const qtyInput = wrapper.querySelector(".item-qty");
            const qty = parseInt(qtyInput?.value) || 1;

            addToCart(itemCode, qty);
        });
    });

    document.querySelectorAll(".add-variants-cart").forEach(button => {
        button.addEventListener("click", function () {
            let itemCode = this.getAttribute("data-item_code");
            if (!itemCode) return;

            fetch(`/api/method/invento_webshop.webshop_functions.variant_selector.utils.get_attributes_and_values?item_code=${itemCode}`, {
                method: "GET",
                headers: HEADERS,
            })
                .then(response => response.json())
                .then(data => {
                    if (data.message && data.message.length > 0) {
                        showVariantSelectionModal(data.message, itemCode);
                    }
                })
                .catch(error => console.error("Error fetching attributes:", error));

        });
    });

    function showVariantSelectionModal(attributes, itemCode) {
        let html = `<form id="variant-form" class="variant-form">`;

        attributes.forEach(attr => {
            html += `
      <div class="variant-group">
        <p class="variant-label">${attr.attribute}</p>

        <div class="variant-options">
          ${attr.values.map(val => {
                const priceHtml = val.price && val.price > 0
                    ? `<span class="variant-price"> (${val.formatted_price})</span>`
                    : "";

                return `
              <label class="variant-option">
                <input
                  type="radio"
                  name="${attr.attribute}"
                  value="${val.value}"
                  required
                />
                <span class="variant-pill">
                  <span class="variant-text">${val.value}</span>
                  ${priceHtml}
                </span>
              </label>
            `;
            }).join("")}
        </div>
      </div>
    `;
        });

        html += `</form>`;

        const footer = `
    <div class="modal-actions">
      <button type="button" class="btn-text" onclick="closeCustomModal()">Cancel</button>
      <button type="button" class="btn-primary" id="add-variant-btn">
        Add to Cart
      </button>
    </div>
  `;

        openCustomModal({
            title: "Select Variant",
            body: html,
            footer
        });

        document.getElementById("add-variant-btn").onclick = function () {
            const form = document.getElementById("variant-form");

            if (!form.checkValidity()) {
                form.reportValidity();
                return;
            }

            const selectedVariants = Object.fromEntries(
                new FormData(form).entries()
            );

            console.log("Item:", itemCode);
            console.log("Variants:", selectedVariants);

            fetch('/api/method/invento_webshop.webshop_functions.variant_selector.utils.get_next_attribute_and_values', {
                method: 'POST',
                headers: HEADERS,
                body: JSON.stringify({
                    item_code: itemCode,
                    selected_attributes: selectedVariants
                }),
            }).then(response => response.json())
                .then(data => {
                    addToCart(data.message, 1)
                })
            closeCustomModal();
        };
    }


    const userImage = frappe.get_cookie('user_image');
    const imageContainer = document.getElementById('user_image');

    if (userImage && imageContainer) {
        imageContainer.innerHTML = '';

        const img = document.createElement('img');
        img.src = userImage;
        img.alt = 'User';
        img.width = 30;
        img.height = 30;

        img.style.borderRadius = '50%';
        img.style.objectFit = 'cover';
        img.style.border = '1px solid black'

        imageContainer.appendChild(img);
    }


    get_cart_items();

    function get_cart_count() {
        const cartCount = frappe.get_cookie("cart_count") || 0;
        const cartCountContainer = document.getElementById("cart_count");
        if (cartCountContainer) {
            cartCountContainer.innerText = cartCount;
        }
    }

    function addToCart(itemCode, qty) {
        const user_id = frappe.get_cookie("user_id");

        // Block guest users
        if (!user_id || user_id === "Guest") {
            Toastify({
                text: "Please login to add items to your cart.",
                close: true,
                gravity: "top",
                position: "center",
                stopOnFocus: true,
                style: {
                    background: "linear-gradient(to right, #ff416c, #ff4b2b)"
                }
            }).showToast();

            // Redirect after short delay
            setTimeout(() => {
                window.location.href = "/login";
            }, 1000);

            return; // stop execution
        }

        fetch("/api/method/invento_webshop.webshop_functions.cart.update_cart", {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
                item_code: itemCode,
                qty: qty,
                cart_items: frappe.get_cookie("cart_items")
            }),
        })
            .then(response => {
                if (!response.ok) {
                    return response.json().then(errData => {
                        throw {
                            status: response.status,
                            message: errData.message || "Something went wrong"
                        };
                    });
                }
                return response.json();
            })
            .then(data => {
                get_cart_count(); // update cart badge
                Toastify({
                    text: "Item added to cart!",
                    close: true,
                    gravity: "top",
                    position: "center",
                    stopOnFocus: true,
                    style: {
                        background: "linear-gradient(to right, #00b09b, #96c93d)"
                    }
                }).showToast();
            })
            .catch(error => {
                console.error("Cart error:", error);
                Toastify({
                    text: error.message || "Failed to add item to cart",
                    close: true,
                    gravity: "top",
                    position: "center",
                    stopOnFocus: true,
                    style: {
                        background: "linear-gradient(to right, #ff5f6d, #ffc371)"
                    }
                }).showToast();
            });
    }


    function get_cart_items() {
        const cookieItems = frappe.get_cookie("cart_items") || "[]";

        fetch(
            `/api/method/invento_webshop.webshop_functions.cart.get_cart_items?cart_items=${cookieItems}`, {
            method: "GET",
            headers: HEADERS
        }
        )
            .then(res => res.json())
            .then(data => {
                get_cart_count();
                const cartItems = data?.message || [];

                const cartContainers = document.querySelectorAll('[id="cart-container"]');
                const template = document.querySelector('#cart-item-template');

                if (!cartContainers.length || !template) return;

                cartContainers.forEach(container => {
                    container.innerHTML = '';
                });

                if (!cartItems.length) {
                    toggle_empty_cart(true);
                    return;
                }

                toggle_empty_cart(false);

                cartItems.forEach(item => {
                    cartContainers.forEach(container => {
                        const cartItem = template.firstElementChild.cloneNode(true);
                        if (!cartItem) return;

                        cartItem.dataset.itemCode = item.item_code;

                        cartItem.querySelector('.item_name') &&
                            (cartItem.querySelector('.item_name').textContent = item.item_name);

                        cartItem.querySelector('.item_qty') &&
                            (cartItem.querySelector('.item_qty').textContent = item.qty);

                        cartItem.querySelector('.item_image') &&
                            (cartItem.querySelector('.item_image').src = item.image);

                        cartItem.querySelector('.item_code') &&
                            (cartItem.querySelector('.item_code').textContent = item.item_code);

                        cartItem.querySelector('.price') &&
                            (cartItem.querySelector('.price').textContent = item.rate);

                        cartItem.querySelector('.amount') &&
                            (cartItem.querySelector('.amount').textContent = item.amount);

                        cartItem.querySelector('.rate p') &&
                            (cartItem.querySelector('.rate p').textContent = item.rate);

                        cartItem.querySelectorAll('.update_cart_qty')?.forEach(btn => {
                            btn.dataset.itemCode = item.item_code;

                            btn.onclick = (e) => {
                                e.stopPropagation();

                                const action = btn.dataset.action;
                                const changeQty = parseInt(btn.dataset.qty) || 1;
                                const qtyEl = cartItem.querySelector('.item_qty');

                                if (!qtyEl) return;

                                let newQty = parseInt(qtyEl.textContent) || 1;
                                newQty += action === "add" ? changeQty : -changeQty;

                                update_cart_qty(item.item_code, changeQty, action);
                                get_cart_count();

                                if (newQty < 1 || action === 'delete') {
                                    cartItem.remove();
                                } else {
                                    qtyEl.textContent = newQty;
                                }
                            };
                        });

                        container.appendChild(cartItem);
                    });
                });
            })
            .catch(err => {
                Toastify({
                    text: err?.message || "Something went wrong",
                    close: true,
                    gravity: "top",
                    position: "center",
                    style: {
                        background: "linear-gradient(to right, #ff5f6d, #ffc371)"
                    }
                }).showToast();
            });

        get_order_details(cookieItems);
    }


    function toggle_empty_cart(isEmpty) {
        const cartSection = document.getElementById("cart-section");
        const emptyCart = document.getElementById("empty-cart");
        const placeOrder = document.getElementById("place-order");

        cartSection && (cartSection.style.display = isEmpty ? 'none' : 'block');
        emptyCart && (emptyCart.style.display = isEmpty ? 'flex' : 'none');
        placeOrder && (placeOrder.style.display = isEmpty ? 'none' : 'flex');
    }



    let isCartUpdateInProgress = false;

    function update_cart_qty(item_code, qty, action) {
        let user_id = frappe.get_cookie("user_id")
        if (user_id === "Guest") {
            window.location.href = "/login"
        }
        if (isCartUpdateInProgress) return; // Prevent multiple simultaneous calls
        isCartUpdateInProgress = true;

        fetch('/api/method/invento_webshop.webshop_functions.cart.update_cart_qty', {
            method: "POST",
            headers: HEADERS,
            body: JSON.stringify({
                item_code: item_code,
                qty: qty,
                action: action,
                cart_items: frappe.get_cookie("cart_items") || "[]"
            })
        })
            .then(response => {
                if (!response.ok) {
                    return response.json().then(errData => {
                        throw {
                            status: response.status,
                            message: errData.message || "Something went wrong"
                        };
                    });
                }
                return response.json();
            })
            .then(data => {
                let item = data.message;
                if (typeof item === 'string') {
                    try {
                        item = JSON.parse(item);
                    } catch (e) {
                        console.error('Error parsing cartItems:', e);
                        item = [];
                    }
                }

                Toastify({
                    text: "Cart Updated!",
                    close: true,
                    gravity: "top",
                    position: "center",
                    stopOnFocus: true,
                    style: {
                        background: "linear-gradient(to right, #00b09b, #96c93d)",
                    }
                }).showToast();

                const cartItems = frappe.get_cookie("cart_items") || "[]";
                get_order_details(cartItems);

                const cartElement = document.getElementById("cart-section");
                const emptyElement = document.getElementById("empty-cart");

                if (item.length === 0 && cartElement && emptyElement) {
                    cartElement.style.display = "none";
                    emptyElement.style.display = 'flex';
                }

                get_cart_count();
            })
            .catch(error => {
                Toastify({
                    text: `❌ Error updating cart: ${error.message || "Unknown error"}`,
                    close: true,
                    gravity: "top",
                    position: "center",
                    stopOnFocus: true,
                    style: {
                        background: "linear-gradient(to right, #ff5f6d, #ffc371)",
                    }
                }).showToast();
            })
            .finally(() => {
                isCartUpdateInProgress = false;
            });
    }

    function get_order_details(cartItems) {
        if (!cartItems) return;

        fetch(`/api/method/invento_webshop.webshop_functions.cart.get_order_details?cart_items=${cartItems}`, {
            method: "GET",
            headers: HEADERS
        })
            .then(response => {
                if (!response.ok) {
                    return response.json().then(errData => {
                        throw {
                            status: response.status,
                            message: errData.message || "Something went wrong"
                        };
                    });
                }
                return response.json();
            })
            .then(data => {
                const orderDetails = data.message;
                if (orderDetails) {
                    // Update subtotals and grand totals
                    const subTotalItems = document.querySelectorAll('[id="sub_total"]');
                    subTotalItems.forEach(el => {
                        el.innerHTML = orderDetails.total_price;
                    });

                    const grandTotalItems = document.querySelectorAll('[id="grand_total"]');
                    grandTotalItems.forEach(el => {
                        el.innerHTML = orderDetails.grand_total;
                    });

                    const taxContainers = document.querySelectorAll('[id="tax_container"]');
                    taxContainers.forEach(taxContainerParent => {
                        let originalTaxTemplate = taxContainerParent.parentElement.querySelector('[id="tax_template"]');
                        if (!originalTaxTemplate) originalTaxTemplate = document.querySelector('[id="tax_template"]');

                        if (originalTaxTemplate) {
                            taxContainerParent.innerHTML = "";
                            orderDetails.order_summary.forEach(summary => {
                                let tempDiv = document.createElement('div');
                                tempDiv.innerHTML = originalTaxTemplate.innerHTML;

                                let nameElement = tempDiv.querySelector('.tax_name');
                                let amountElement = tempDiv.querySelector('.tax_amount');

                                if (nameElement) {
                                    // If it's a shipping row, render a select field instead of text
                                    if (summary.is_shipping && orderDetails.available_shipping_rules.length > 0) {
                                        let select = document.createElement('select');
                                        select.className = 'form-control shipping-rule-dropdown';
                                        select.style.padding = '2px 5px';
                                        select.style.fontSize = '0.9em';

                                        orderDetails.available_shipping_rules.forEach(rule => {
                                            let opt = document.createElement('option');
                                            opt.value = rule.name;
                                            opt.text = rule.label;
                                            opt.selected = rule.name === orderDetails.selected_shipping_rule;
                                            select.appendChild(opt);
                                        });

                                        select.addEventListener('change', (e) => {
                                            onShippingRuleChange(e.target.value, cartItems);
                                        });

                                        nameElement.innerHTML = "";
                                        nameElement.appendChild(select);
                                    } else {
                                        nameElement.innerText = summary.included_in_price === 1 ? `${summary.description} (Inc)` : summary.description;
                                    }
                                }

                                if (amountElement) {
                                    amountElement.innerText = summary.tax_amount;
                                }
                                taxContainerParent.appendChild(tempDiv);
                            });
                        }
                    });
                }
            })
            .catch(error => {
                console.error("Error fetching order details:", error);
            });
    }

    function onShippingRuleChange(shippingRule, cartItems) {
        if (!shippingRule) return;

        fetch('/api/method/invento_webshop.api.shipping.update_order_with_shipping', {
            method: 'POST',
            headers: HEADERS,
            body: JSON.stringify({
                shipping_rule: shippingRule
            })
        })
            .then(res => res.json())
            .then(() => {
                // Refresh order details to update the totals and taxes
                get_order_details(cartItems);
            })
            .catch(err => console.error("Failed to update shipping:", err));
    }

    const searchInputs = document.querySelectorAll('#search-input');

    searchInputs.forEach(searchInput => {
        // Find the nearest product_search AFTER this input
        const container = searchInput.closest('section, div');
        const productSearch = container?.querySelector('#product_search');

        if (!productSearch) return;

        productSearch.style.display = "none";
        const originalContent = productSearch.innerHTML;
        productSearch.innerHTML = "";

        function positionProductSearch() {
            const rect = searchInput.getBoundingClientRect();
            productSearch.style.position = "fixed";
            productSearch.style.top = `${rect.bottom}px`;
            productSearch.style.left = `${rect.left}px`;
            productSearch.style.width = `${rect.width}px`;
            productSearch.style.zIndex = "1000";
            productSearch.style.display = "block";
        }

        function debounce(fn, delay) {
            let t;
            return (...args) => {
                clearTimeout(t);
                t = setTimeout(() => fn.apply(this, args), delay);
            };
        }

        function doSearch() {
            const searchTerm = searchInput.value.trim().toLowerCase();

            if (!searchTerm) {
                productSearch.innerHTML = "";
                productSearch.style.display = "none";
                return;
            }

            fetch(
                `/api/method/invento_webshop.api.item.search_items?search=${encodeURIComponent(searchTerm)}`, {
                method: "GET",
                headers: HEADERS
            }
            )
                .then(res => res.json())
                .then(data => {
                    const items = data?.message?.items || [];
                    const fragment = document.createDocumentFragment();

                    items.forEach(product => {
                        const temp = document.createElement("div");
                        temp.innerHTML = originalContent;

                        const itemEl = temp.querySelector(".item");
                        if (itemEl) itemEl.href = product.custom_route;

                        const nameEl = temp.querySelector(".product_name p");
                        if (nameEl) nameEl.textContent = product.item_name;

                        const imgEl = temp.querySelector(".product_image");
                        if (imgEl) imgEl.src = product.image;

                        fragment.appendChild(temp);
                    });

                    productSearch.innerHTML = "";
                    productSearch.appendChild(fragment);
                    positionProductSearch();
                });
        }

        const handleSearch = debounce(doSearch, 600);
        searchInput.addEventListener("input", handleSearch);
    });
});

frappe.get_cookie = function getCookie(name) {
    return frappe.get_cookies()[name];
};

frappe.get_cookies = function getCookies() {
    var c = document.cookie,
        v = 0,
        cookies = {};
    if (document.cookie.match(/^\s*\$Version=(?:"1"|1);\s*(.*)/)) {
        c = RegExp.$1;
        v = 1;
    }
    if (v === 0) {
        c.split(/[,;]/).map(function (cookie) {
            var parts = cookie.split(/=/, 2),
                name = decodeURIComponent(parts[0].trimLeft()),
                value = parts.length > 1 ? decodeURIComponent(parts[1].trimRight()) : null;
            if (value && value.charAt(0) === '"') {
                value = value.substr(1, value.length - 2);
            }
            cookies[name] = value;
        });
    } else {
        c.match(/(?:^|\s+)([!#$%&'*+\-.0-9A-Z^`a-z|~]+)=([!#$%&'*+\-.0-9A-Z^`a-z|~]*|"(?:[\x20-\x7E\x80\xFF]|\\[\x00-\x7F])*")(?=\s*[,;]|$)/g).map(function ($0, $1) {
            var name = $0,
                value = $1.charAt(0) === '"' ? $1.substr(1, -1).replace(/\\(.)/g, "$1") : $1;
            cookies[name] = value;
        });
    }
    return cookies;
};


