        const preferences = {
            essential: true,
            analytics: analytics,
            marketing: marketing,
            timestamp: new Date().getTime()
        };
        savePreferences(preferences);
    }

    function savePreferences(preferences) {
        localStorage.setItem(COOKIE_PREFERENCE_KEY, JSON.stringify(preferences));
        const container = document.getElementById('cookie-banner-container');
        if (container) {
            container.classList.remove('show-banner');
