:root {
    --primary-text: #171307;
    --accent-yellow: #FFED00;
    --bg-white: #ffffff;
    --bg-offwhite: #FFFDF5;
    --gray-text: #52504c;
    --border-light: #e0e0e0;
    --font-main: 'IBM Plex Sans', sans-serif;
    --font-secondary: 'Inter', sans-serif;
}

.cookie-banner-wrapper {
    position: fixed !important;
    bottom: 0 !important;
    left: 0 !important;
    width: 95% !important;
    max-width: 95% !important;
    z-index: 10000 !important;
    pointer-events: none !important;
}

.cookie-banner-container-aligned {
    max-width: 500px !important;
    width: 100% !important;
    margin-left: 0 !important;
    padding: 20px !important; /* Some padding from the edges */
    display: flex !important;
    justify-content: flex-start !important; 
    pointer-events: none !important;
}

#cookie-banner-container {
    width: 100% !important;
    max-width: none !important; /* Allow it to fill the 95% container */
    margin: 0 !important; /* No child margin */
    background: #ffffff !important;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1) !important;
    border-radius: 12px !important;
    font-family: 'IBM Plex Sans', sans-serif !important;
    color: #171307 !important;
    display: none;
    overflow: hidden !important;
    border: 1px solid #e0e0e0 !important;
    pointer-events: auto !important;
    opacity: 0;
    transform: translateY(20px);
}

#cookie-banner-container.show-banner {
    display: block !important;
    animation: cookieSlideUp 0.6s ease-out forwards !important;
}

@keyframes cookieSlideUp {
    from {
        opacity: 0;
        transform: translateY(40px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

.cookie-banner-content {
    padding: 24px;
}

.cookie-banner-header {
    font-size: 20px;
    font-weight: 600;
    margin-bottom: 12px;
}

.cookie-banner-desc {
    font-size: 14px;
    line-height: 1.6;
    color: var(--gray-text);
    margin-bottom: 24px;
}

.cookie-banner-buttons {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
}

.btn-cookie {
    flex: 1;
    padding: 12px 16px;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    text-align: center;
    border: none;
}

.btn-accept {
    background-color: var(--accent-yellow);
    color: #000;
}

.btn-accept:hover {
    filter: brightness(0.95);
}

.btn-reject {
    background-color: #f4f4f4;
    color: var(--primary-text);
}

.btn-reject:hover {
    background-color: #e8e8e8;
}

.btn-settings {
    display: block;
    width: 100%;
    background: transparent;
    color: var(--primary-text);
    text-decoration: underline;
    font-size: 13px;
    padding: 8px 0;
    border: none;
    cursor: pointer;
}

/* Settings View */
.cookie-settings-view {
    display: none;
    max-height: 400px;
    overflow-y: auto;
    padding-top: 10px;
    border-top: 1px solid var(--border-light);
    margin-top: 20px;
}

.cookie-category {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    margin-bottom: 20px;
}

.category-info {
    flex: 1;
    padding-right: 20px;
}

.category-name {
    font-size: 15px;
    font-weight: 600;
    margin-bottom: 4px;
}

.category-desc {
    font-size: 13px;
    color: var(--gray-text);
    line-height: 1.4;
}

/* Toggle Switch */
.switch {
    position: relative !important;
    display: block !important;
    width: 44px !important;
    height: 24px !important;
    flex-shrink: 0 !important;
    margin-left: 10px;
}

.switch input {
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
    position: absolute !important;
}

.slider {
    position: absolute !important;
    cursor: pointer !important;
    top: 0 !important;
    left: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    background-color: #ccc !important;
    transition: .4s !important;
    border-radius: 24px !important;
    display: block !important;
}

.slider:before {
    position: absolute !important;
    content: "" !important;
    height: 18px !important;
    width: 18px !important;
    left: 3px !important;
    bottom: 3px !important;
    background-color: white !important;
    transition: .4s !important;
    border-radius: 50% !important;
}

input:checked + .slider {
    background-color: #FFED00 !important; /* Direct color instead of var for robustness */
}

input:focus + .slider {
    box-shadow: 0 0 1px #FFED00 !important;
}

input:checked + .slider:before {
    transform: translateX(20px) !important;
}

input:disabled + .slider {
    opacity: 0.5 !important;
    cursor: not-allowed !important;
}

.footer-save-btn {
    margin-top: 10px;
    width: 100%;
}

@media (max-width: 480px) {
    #cookie-banner-container {
        left: 10px;
        right: 10px;
        bottom: 10px;
    }
    .cookie-banner-buttons {
        flex-direction: column;
    }
}
